import{f as a,o,c as i,a2 as d}from"./chunks/framework.Cd9rfTEn.js";const R=JSON.parse('{"title":"Casos de prueba de aceptación — T08 NFR — Requisitos no funcionales, seguridad, privacidad, observabilidad y calidad","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/20-casos-prueba/T08-NFR-no-funcionales-seguridad.md","filePath":"entregables-analisis-diseno/20-casos-prueba/T08-NFR-no-funcionales-seguridad.md","lastUpdated":null}'),t={name:"entregables-analisis-diseno/20-casos-prueba/T08-NFR-no-funcionales-seguridad.md"};function n(c,e,r,s,l,u){return o(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="casos-de-prueba-de-aceptacion-—-t08-nfr-—-requisitos-no-funcionales-seguridad-privacidad-observabilidad-y-calidad" tabindex="-1">Casos de prueba de aceptación — T08 NFR — Requisitos no funcionales, seguridad, privacidad, observabilidad y calidad <a class="header-anchor" href="#casos-de-prueba-de-aceptacion-—-t08-nfr-—-requisitos-no-funcionales-seguridad-privacidad-observabilidad-y-calidad" aria-label="Permalink to &quot;Casos de prueba de aceptación — T08 NFR — Requisitos no funcionales, seguridad, privacidad, observabilidad y calidad&quot;">​</a></h1><p>Parte de <a href="./../20-casos-prueba"><code>20-casos-prueba.md</code></a> (artefacto 9.2). Fuente: <a href="./../../especificacion/anexos/T08-NFR-no-funcionales-seguridad"><code>T08-NFR-no-funcionales-seguridad.md</code></a> (solo lectura). Generado por <code>_trabajo/gen_casos_prueba.py</code> y revisado; ante diferencias prevalece el anexo.</p><p>Resumen: 25 CP de requisitos funcionales, 5 CP de escenarios ESC y 16 CP de casos de uso CU.</p><p>Convenciones: el formato Dado / Cuando / Entonces sigue <code>07-estrategia-pruebas.md</code> §13; la ola de un CP de RF es la del prompt que lo implementa en <code>03</code> (prevalece sobre la columna del anexo); la de un CP de escenario es la última ola de los RF que cita o la que el escenario declara. Prioridad Extensión del anexo se agrupa como Estándar. Todos los datos son ficticios (TEN-001, TEN-002 y semillas del §18 del anexo).</p><h2 id="_1-casos-por-requisito-funcional" tabindex="-1">1. Casos por requisito funcional <a class="header-anchor" href="#_1-casos-por-requisito-funcional" aria-label="Permalink to &quot;1. Casos por requisito funcional&quot;">​</a></h2><p>Precondiciones comunes de esta sección: ola indicada desplegada en <code>staging</code> o <code>sandbox</code>; tenant ficticio TEN-001 con la configuración publicada y las semillas del T08 §18; usuario con la capability que exige el RF (el caso negativo sin capability lo cubre la suite de permisos negativos, <code>07</code> §4.3). Resultado esperado: el criterio de aceptación del RF se cumple, la prueba automatizada cita el RF y el CP en su nombre, y quedan auditoría y evento cuando hay cambio persistente.</p><h3 id="_1-1-requisitos-funcionales-propios-del-anexo-t08-§5-1" tabindex="-1">1.1 Requisitos funcionales propios del anexo (T08 §5.1) <a class="header-anchor" href="#_1-1-requisitos-funcionales-propios-del-anexo-t08-§5-1" aria-label="Permalink to &quot;1.1 Requisitos funcionales propios del anexo (T08 §5.1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-NFR-0001</td><td>RF-NFR-001; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 con Bloqueo legal: LH-DEMO-001 sobre la cuenta de ASO-003 por &quot;litigio&quot; ficticio, <code>activo</code></td><td>Inventario de datos personales por entidad/colección: campo, categoría (identificatorio, contacto, fiscal, financiero, ubicación, salud, laboral, imagen, comunicación), sensibilidad (<code>publica</code>, <code>interna</code>, <code>personal</code>, <code>sensible</code>…</td><td>Un script de CI falla si un campo nuevo no declara <code>x-pii</code>; la pantalla lista el 100 % de los campos declarados.</td></tr><tr><td>CP-NFR-0002</td><td>RF-NFR-002; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Registro de tratamientos: Plantilla completa de 12 finalidades (RF-NFR-002) en TEN-001; TEN-002 con 3 personalizadas</td><td>Registro de actividades de tratamiento por tenant, con plantilla precargada (gestión del suministro, facturación y cobranza, atención y reclamos, técnica y campo, comunicaciones institucionales, comunicaciones promocionales…</td><td>El tenant puede exportar el registro en XLSX/PDF; cada entrada tiene versión y fecha.</td></tr><tr><td>CP-NFR-0003</td><td>RF-NFR-003; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Avisos: AVI-DEMO-001 v1 y v2 (landing), AVI-DEMO-002 v1 (app)</td><td>Avisos de privacidad versionados por tenant y canal (landing, registro, app, formulario presencial), con contenido mínimo del art. 6 (finalidad, destinatarios, existencia del archivo y responsable, obligatoriedad, consecuencias, derechos)…</td><td>Cambiar el aviso crea versión nueva; los consentimientos previos quedan ligados a la versión aceptada.</td></tr><tr><td>CP-NFR-0004</td><td>RF-NFR-004; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Registro de tratamientos: Plantilla completa de 12 finalidades (RF-NFR-002) en TEN-001; TEN-002 con 3 personalizadas</td><td>Registro de consentimientos y preferencias: titular, finalidad, versión del aviso, canal, fecha, evidencia (IP truncada, agente de usuario, firma o formulario escaneado), estado (otorgado, revocado, vencido), revocación en un paso.</td><td>Revocar el consentimiento promocional impide en ≤ 5 min que el motor de audiencia (T09) incluya al titular.</td></tr><tr><td>CP-NFR-0005</td><td>RF-NFR-005; T08 §5.1; PRO-O2-18</td><td>O2</td><td>Estándar</td><td>regla</td><td>TEN-001 con Evidencia: Release 0.0.1-demo con todos los checks en verde y un SCA con una vulnerabilidad media aceptada con vencimiento</td><td>Separación de comunicaciones institucionales/transaccionales (factura, vencimiento, corte, reclamo) y promocionales; las promocionales exigen consentimiento u oposición respetada y consulta del Registro Nacional &quot;No Llame&quot; para llamadas y…</td><td>Una campaña promocional excluye a quienes revocaron o figuran en el registro; queda evidencia de la consulta.</td></tr><tr><td>CP-NFR-0006</td><td>RF-NFR-006; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Solicitudes: DSR-2026-000001 (acceso, <code>respondida</code>), DSR-2026-000002 (supresión con bloqueo de facturas, <code>pendienteAprobacion</code>), DSR-2026-000003 (rectificación…</td><td>Bandeja de solicitudes de derechos (acceso, rectificación, actualización, supresión, oposición, revocación) con canal de ingreso (PWA, landing, presencial, correo), verificación de identidad proporcional, plazos legales visibles (acceso…</td><td>Una solicitud de acceso genera el informe en ≤ 10 días corridos; la bandeja alerta al 70 % del plazo.</td></tr><tr><td>CP-NFR-0007</td><td>RF-NFR-007; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Tenants: TEN-001 &quot;Cooperativa Ejemplo A&quot; (<code>America/Argentina/Cordoba</code>), TEN-002 &quot;Cooperativa Ejemplo B&quot; (<code>America/Argentina/Buenos_Aires</code>), TEN-099…</td><td>Informe de acceso del titular: generación automática (job <code>nfr:informe-acceso</code>) de todos los datos del titular en el tenant, en lenguaje claro, PDF y JSON legible, excluyendo datos de terceros y secretos.</td><td>El informe incluye cada colección marcada con <code>x-pii</code> en que figure el titular; prueba automatizada con titular ficticio en 2 tenants muestra solo los del tenant solicitado.</td></tr><tr><td>CP-NFR-0008</td><td>RF-NFR-008; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Bloqueo legal: LH-DEMO-001 sobre la cuenta de ASO-003 por &quot;litigio&quot; ficticio, <code>activo</code></td><td>Supresión compatible con obligaciones de conservación: si hay bloqueo legal o plazo vigente, se <strong>bloquea</strong> el tratamiento (solo consulta para la obligación) y se programa la supresión o anonimización al vencer; si no, se suprime o…</td><td>Suprimir un socio con facturas de hace 3 años no borra facturas; anonimiza contacto y comunicación no obligatorios y marca bloqueo.</td></tr><tr><td>CP-NFR-0009</td><td>RF-NFR-009; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Usuarios: USR-ADM-A (admin TEN-001, MFA requerido), USR-CAJ-01 (cajero), USR-DPO-A (responsable de datos TEN-001), USR-AUD-A (auditor), USR-ADM-B (admin…</td><td>Políticas de conservación por categoría de dato y tipo de documento, parametrizables por tenant dentro de mínimos y máximos de plataforma, con job diario de aplicación (<code>nfr:aplicar-conservacion</code>) y reporte previo de impacto.</td><td>Un ensayo con datos ficticios vencidos muestra el reporte previo, la aprobación y el resultado; nada se elimina sin aprobación de la primera ejecución por categoría.</td></tr><tr><td>CP-NFR-0010</td><td>RF-NFR-010; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Bloqueo legal: LH-DEMO-001 sobre la cuenta de ASO-003 por &quot;litigio&quot; ficticio, <code>activo</code></td><td>Bloqueos legales (litigio, requerimiento judicial o administrativo, auditoría fiscal) sobre titular, cuenta, documento o período, con motivo, responsable, vigencia y aprobación a dos firmas.</td><td>Un bloqueo activo hace que el job de conservación omita esos datos y lo registre.</td></tr><tr><td>CP-NFR-0011</td><td>RF-NFR-011; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Registro de tratamientos: Plantilla completa de 12 finalidades (RF-NFR-002) en TEN-001; TEN-002 con 3 personalizadas</td><td>Anonimización irreversible para BI histórico y para titulares suprimidos: sustitución de identificadores, generalización de domicilio a localidad, fechas a mes, eliminación de texto libre e imágenes.</td><td>Pruebas de reidentificación: ningún registro anonimizado conserva DNI, CUIT, nombre, correo, teléfono, calle ni coordenadas.</td></tr><tr><td>CP-NFR-0012</td><td>RF-NFR-012; T08 §5.1; PRO-O2-18</td><td>O2</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Solicitudes: DSR-2026-000001 (acceso, <code>respondida</code>), DSR-2026-000002 (supresión con bloqueo de facturas, <code>pendienteAprobacion</code>), DSR-2026-000003 (rectificación…</td><td>Portal &quot;Mis datos y privacidad&quot; del socio/empleado: ver datos, descargar informe, pedir rectificación, revocar consentimientos, ver avisos aceptados y estado de solicitudes.</td><td>Recorrido e2e Playwright con socio ficticio.</td></tr><tr><td>CP-NFR-0013</td><td>RF-NFR-013; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Registro de tratamientos: Plantilla completa de 12 finalidades (RF-NFR-002) en TEN-001; TEN-002 con 3 personalizadas</td><td>Registro de subencargados de plataforma (proveedor, servicio, datos tratados, país, garantía de transferencia, fecha de alta) visible para cada tenant, con aviso al tenant ≥ 30 días antes de incorporar uno nuevo.</td><td>El tenant ve la lista vigente y el historial; un alta genera notificación.</td></tr><tr><td>CP-NFR-0014</td><td>RF-NFR-014; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Registro de tratamientos: Plantilla completa de 12 finalidades (RF-NFR-002) en TEN-001; TEN-002 con 3 personalizadas</td><td>Registro y gestión de incidentes de seguridad y de datos personales: detección, clasificación, contención, evaluación de datos afectados por tenant, notificación al tenant, soporte a la notificación a titulares/AAIP, lecciones y cierre.</td><td>Un simulacro anual cumple los plazos de notificación de PA-NFR-08 con evidencia.</td></tr><tr><td>CP-NFR-0015</td><td>RF-NFR-015; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Simulacro: RST-DEMO-001 restauración selectiva de TEN-001 con RPO medido 4 min y RTO 3 h 10 min (valores ilustrativos)</td><td>Simulacros de restauración: plan, ejecución, mediciones (RPO real, RTO real), verificación de integridad y conciliación externa, acta.</td><td>Un simulacro mensual de plataforma y uno trimestral por tenant piloto con acta firmada.</td></tr><tr><td>CP-NFR-0016</td><td>RF-NFR-016; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Alertas: ALR-DEMO-001 &quot;Certificado ARCA vence en 29 días&quot; (certificado ficticio), ALR-DEMO-002 &quot;Lag de outbox &gt; 60 s&quot; resuelta</td><td>Tablero de salud de plataforma: disponibilidad por servicio, latencias, errores, colas, jobs, integraciones, backups, certificados próximos a vencer, alertas activas, consumo por tenant.</td><td>El tablero muestra datos con antigüedad ≤ 60 s.</td></tr><tr><td>CP-NFR-0017</td><td>RF-NFR-017; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Alertas: ALR-DEMO-001 &quot;Certificado ARCA vence en 29 días&quot; (certificado ficticio), ALR-DEMO-002 &quot;Lag de outbox &gt; 60 s&quot; resuelta</td><td>Tablero de salud del tenant: estado de procesos (lotes, emisión fiscal, cobranzas, sincronizaciones), integraciones (último éxito, errores, credenciales por vencer), cuotas consumidas e incidentes de plataforma que lo afectan.</td><td>Un certificado ARCA que vence en ≤ 30 días aparece como alerta.</td></tr><tr><td>CP-NFR-0018</td><td>RF-NFR-018; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Solicitudes: DSR-2026-000001 (acceso, <code>respondida</code>), DSR-2026-000002 (supresión con bloqueo de facturas, <code>pendienteAprobacion</code>), DSR-2026-000003 (rectificación…</td><td>Reglas de alerta técnica configurables (condición, severidad, destinatarios, deduplicación, reconocimiento, resolución, vínculo al objeto).</td><td>Una alerta repetida dentro de la ventana de deduplicación no genera una segunda notificación.</td></tr><tr><td>CP-NFR-0019</td><td>RF-NFR-019; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Estándar</td><td>regla</td><td>TEN-001 con Usuarios: USR-ADM-A (admin TEN-001, MFA requerido), USR-CAJ-01 (cajero), USR-DPO-A (responsable de datos TEN-001), USR-AUD-A (auditor), USR-ADM-B (admin…</td><td>Página de estado de la plataforma y aviso en el admin de incidentes y mantenimientos programados.</td><td>Un mantenimiento programado se publica ≥ 72 h antes.</td></tr><tr><td>CP-NFR-0020</td><td>RF-NFR-020; T08 §5.1; PRO-O0-06</td><td>O0</td><td>Estándar</td><td>regla</td><td>TEN-001 con Tenants: TEN-001 &quot;Cooperativa Ejemplo A&quot; (<code>America/Argentina/Cordoba</code>), TEN-002 &quot;Cooperativa Ejemplo B&quot; (<code>America/Argentina/Buenos_Aires</code>), TEN-099…</td><td>Recepción de reportes CSP y de violaciones de seguridad del navegador (<code>report-to</code>), agregados y deduplicados.</td><td>Un reporte de violación aparece en <code>cspReports</code> en ≤ 1 min.</td></tr><tr><td>CP-NFR-0021</td><td>RF-NFR-021; T08 §5.1; PRO-O0-06</td><td>O0</td><td>Estándar</td><td>regla</td><td>TEN-001 con Usuarios: USR-ADM-A (admin TEN-001, MFA requerido), USR-CAJ-01 (cajero), USR-DPO-A (responsable de datos TEN-001), USR-AUD-A (auditor), USR-ADM-B (admin…</td><td>Publicación de <code>/.well-known/security.txt</code> y política de divulgación responsable.</td><td>El archivo responde con contacto y vencimiento válidos.</td></tr><tr><td>CP-NFR-0022</td><td>RF-NFR-022; T08 §5.1; PRO-O0-02</td><td>O0</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Evidencia: Release 0.0.1-demo con todos los checks en verde y un SCA con una vulnerabilidad media aceptada con vencimiento</td><td>Evidencia de liberación por versión: resultados de pruebas, cobertura, SCA, SAST, DAST, imágenes escaneadas, SBOM, pruebas de carga cuando corresponda y aprobaciones.</td><td>No se puede promover a producción una versión sin evidencia completa (gate del pipeline).</td></tr><tr><td>CP-NFR-0023</td><td>RF-NFR-023; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Estándar</td><td>seguridad</td><td>TEN-001 con Claves: Metadatos de DEK por tenant (sin material), una en <code>soloDescifrado</code></td><td>Consola de claves: listado de claves de cifrado y firma (metadatos, nunca material), fecha de creación, próxima rotación, estado, y rotación manual con doble aprobación.</td><td>Una rotación manual re-envuelve todas las DEK de un tenant sin indisponibilidad.</td></tr><tr><td>CP-NFR-0024</td><td>RF-NFR-024; T08 §5.1; PRO-O0-06</td><td>O0</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Registro de tratamientos: Plantilla completa de 12 finalidades (RF-NFR-002) en TEN-001; TEN-002 con 3 personalizadas</td><td>Restricción y registro de exportaciones con datos personales: motivo opcional, tope de filas por rol, marca de agua con usuario y fecha en PDF/XLSX, vencimiento del archivo generado.</td><td>Cada exportación queda en auditoría con filtros, cantidad y destino; el archivo expira a las 24 h.</td></tr><tr><td>CP-NFR-0025</td><td>RF-NFR-025; T08 §5.1; PRO-O1-18</td><td>O1</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Usuarios: USR-ADM-A (admin TEN-001, MFA requerido), USR-CAJ-01 (cajero), USR-DPO-A (responsable de datos TEN-001), USR-AUD-A (auditor), USR-ADM-B (admin…</td><td>Gestión de cuotas por tenant (requests por minuto, jobs concurrentes, almacenamiento, exportaciones, consumo de IA, llamadas BI) visible en el tablero del tenant y en plataforma.</td><td>Superar la cuota devuelve 429 con <code>Retry-After</code> y la cuota consumida se ve en el tablero.</td></tr></tbody></table><h2 id="_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" tabindex="-1">2. Casos por escenario y criterio de aceptación con ID <a class="header-anchor" href="#_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" aria-label="Permalink to &quot;2. Casos por escenario y criterio de aceptación con ID&quot;">​</a></h2><p><strong>CP-NFR-5001 — ESC-01. Pago excedente de un hermano: A debe ARS 13.000 y paga ARS 15.000; B tiene deuda propia; se confirman 13.000 contra A y 2.000 quedan a…</strong></p><ul><li>Cubre: ESC-01; RNF-NFR-152, RNF-NFR-204, RNF-NFR-205, RNF-NFR-212, RNF-NFR-213, RNF-NFR-218, RNF-NFR-229; T08 §17.1</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: integración</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Dataset de carga: Generador <code>seed:carga --perfil=grande</code> con 150.000 suministros y 5 años de movimientos sintéticos, solo en staging</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Pago excedente de un hermano: A debe ARS 13.000 y paga ARS 15.000; B tiene deuda propia; se confirman 13.000 contra A y 2.000 quedan a favor o pendientes; no se paga a B.</li><li>Entonces Prueba de integración y e2e con dataset canónico; propiedad monetaria &quot;no se crea ni se pierde un centavo&quot;; webhook triplicado.</li></ul><p><strong>CP-NFR-5002 — ESC-02. Corrección recibida después de emitir: emitido ARS 12.000, recalculado ARS 15.000; se simula la diferencia de ARS 3.000, se aprueba y se…</strong></p><ul><li>Cubre: ESC-02; RNF-NFR-230, RNF-NFR-110, RNF-NFR-179, RNF-NFR-223; T08 §17.1</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Tenants: TEN-001 &quot;Cooperativa Ejemplo A&quot; (<code>America/Argentina/Cordoba</code>), TEN-002 &quot;Cooperativa Ejemplo B&quot; (<code>America/Argentina/Buenos_Aires</code>), TEN-099 &quot;Cooperativa en baja&quot; (para RNF-NFR-108); todos con <code>isFictitious: true</code></li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Corrección recibida después de emitir: emitido ARS 12.000, recalculado ARS 15.000; se simula la diferencia de ARS 3.000, se aprueba y se conserva el original.</li><li>Entonces Prueba de que la simulación no escribe; que el original no cambia (hash RNF-NFR-230); auditoría del ajuste.</li></ul><p><strong>CP-NFR-5003 — ESC-03. Instalación offline en conflicto: la orden se modifica mientras el instalador está sin conexión; al sincronizar se conserva la evidencia y…</strong></p><ul><li>Cubre: ESC-03; RNF-NFR-017, RNF-NFR-156, RNF-NFR-187, RNF-NFR-190, RNF-NFR-213, RNF-NFR-219; T08 §17.1</li><li>Ola: O3 · Prioridad: Núcleo · Tipo: integración</li><li>Precondiciones: ola O3 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Evidencia: Release 0.0.1-demo con todos los checks en verde y un SCA con una vulnerabilidad media aceptada con vencimiento</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Instalación offline en conflicto: la orden se modifica mientras el instalador está sin conexión; al sincronizar se conserva la evidencia y se detecta el conflicto, sin duplicar salida de equipo.</li><li>Entonces Suite Playwright offline + integración de sincronización.</li></ul><p><strong>CP-NFR-5004 — ESC-04. Recuperación con operaciones externas posteriores a la copia: se restaura información anterior a un pago o emisión fiscal; se reconcilian…</strong></p><ul><li>Cubre: ESC-04; RNF-NFR-037, RNF-NFR-043, RNF-NFR-044, RNF-NFR-045, RNF-NFR-217, RNF-NFR-221; T08 §17.1</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Simulacro: RST-DEMO-001 restauración selectiva de TEN-001 con RPO medido 4 min y RTO 3 h 10 min (valores ilustrativos)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Recuperación con operaciones externas posteriores a la copia: se restaura información anterior a un pago o emisión fiscal; se reconcilian identificadores externos y no se reenvía.</li><li>Entonces Simulacro trimestral con emisión y pago posteriores al punto de restauración.</li></ul><p><strong>CP-NFR-5005 — ESC-05. Cambio de condiciones en un período parcialmente procesado: el lote mantiene universo y versiones aplicadas; reejecutar no reescribe…</strong></p><ul><li>Cubre: ESC-05; RNF-NFR-013, RNF-NFR-179, RNF-NFR-215, RNF-NFR-216, RNF-NFR-223; T08 §17.1</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Personas: ASO-001 (socia, con MFA), ASO-002 y ASO-003 (hermanos, mismo domicilio ficticio), ADH-001 (menor adherente con representante ASO-002); documentos y CUIT generados con dígito verificador válido en rango ficticio; correos…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Cambio de condiciones en un período parcialmente procesado: el lote mantiene universo y versiones aplicadas; reejecutar no reescribe documentos.</li><li>Entonces Prueba de lote con cambio tarifario a mitad; reejecución sin cambios.</li></ul><h2 id="_3-casos-por-caso-de-uso-cu" tabindex="-1">3. Casos por caso de uso (CU) <a class="header-anchor" href="#_3-casos-por-caso-de-uso-cu" aria-label="Permalink to &quot;3. Casos por caso de uso (CU)&quot;">​</a></h2><p><strong>CP-NFR-8001 — CU-29. Alta de USR-CAJ-01 con rol Cajero en TEN-001 restringido a sucursal; intento de cambiar tarifa o anular sin aprobación es denegado y…</strong></p><ul><li>Cubre: CU-29; RNF-NFR-062, RNF-NFR-090, RNF-NFR-110, RNF-NFR-115, RNF-NFR-150; T08 §16.1</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Usuarios: USR-ADM-A (admin TEN-001, MFA requerido), USR-CAJ-01 (cajero), USR-DPO-A (responsable de datos TEN-001), USR-AUD-A (auditor), USR-ADM-B (admin TEN-002), USR-PLAT-01 (plataforma), USR-SRE-01</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Alta de USR-CAJ-01 con rol Cajero en TEN-001 restringido a sucursal; intento de cambiar tarifa o anular sin aprobación es denegado y registrado; al perder la función se revocan permisos y sesiones.</li><li>Entonces RNF-NFR-062 (revocación ≤ 60 s), RNF-NFR-090, RNF-NFR-110, RNF-NFR-115, RNF-NFR-150.</li></ul><p><strong>CP-NFR-8002 — CU-GOB-01. Cambio de BON-VAR-30 del 30 % al 20 % con vigencia futura y aprobación; evidencia visible al usuario autorizado; TEN-002 no ve los eventos</strong></p><ul><li>Cubre: CU-GOB-01; RNF-NFR-110, RNF-NFR-117, RNF-NFR-148; T08 §16.1</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Evidencia: Release 0.0.1-demo con todos los checks en verde y un SCA con una vulnerabilidad media aceptada con vencimiento</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Cambio de BON-VAR-30 del 30 % al 20 % con vigencia futura y aprobación; evidencia visible al usuario autorizado; TEN-002 no ve los eventos.</li><li>Entonces RNF-NFR-110 a 113, RNF-NFR-117, RNF-NFR-148.</li></ul><p><strong>CP-NFR-8003 — CU-API-01. CLI-BI-A con alcances <code>facturacion:leer</code> y <code>cobranza:leer</code> consulta TEN-001 paginado con fecha de corte; no accede a TEN-002 ni modifica…</strong></p><ul><li>Cubre: CU-API-01; RNF-NFR-019, RNF-NFR-022, RNF-NFR-103, RNF-NFR-233, RNF-NFR-175; T08 §16.1</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Tenants: TEN-001 &quot;Cooperativa Ejemplo A&quot; (<code>America/Argentina/Cordoba</code>), TEN-002 &quot;Cooperativa Ejemplo B&quot; (<code>America/Argentina/Buenos_Aires</code>), TEN-099 &quot;Cooperativa en baja&quot; (para RNF-NFR-108); todos con <code>isFictitious: true</code></li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando CLI-BI-A con alcances <code>facturacion:leer</code> y <code>cobranza:leer</code> consulta TEN-001 paginado con fecha de corte; no accede a TEN-002 ni modifica; revocación efectiva.</li><li>Entonces RNF-NFR-019, RNF-NFR-022, RNF-NFR-103, RNF-NFR-233, RNF-NFR-175.</li></ul><p><strong>CP-NFR-8004 — CU-SEG-01. USR-ADM-A registra factor, opera con verificación reforzada, recupera contraseña sin perder el factor y usa el procedimiento de pérdida de…</strong></p><ul><li>Cubre: CU-SEG-01; RNF-NFR-060, RNF-NFR-231, RNF-NFR-232; T08 §16.1</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001 y TEN-002; semillas de T08 §18.</li><li>Datos de prueba: Tenants: TEN-001 &quot;Cooperativa Ejemplo A&quot; (<code>America/Argentina/Cordoba</code>), TEN-002 &quot;Cooperativa Ejemplo B&quot; (<code>America/Argentina/Buenos_Aires</code>), TEN-099 &quot;Cooperativa en baja&quot; (para RNF-NFR-108); todos con <code>isFictitious: true</code></li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando USR-ADM-A registra factor, opera con verificación reforzada, recupera contraseña sin perder el factor y usa el procedimiento de pérdida de factor; se notifican cambios e invalidan sesiones.</li><li>Entonces RNF-NFR-060 a 066, RNF-NFR-231, RNF-NFR-232.</li></ul><p><strong>CP-NFR-8005 — CU-ARQ-01. Pedido de Internet que pasa por CRM, técnica, contratos y ERP sin que un reintento genere dos contratos o dos facturas</strong></p><ul><li>Cubre: CU-ARQ-01; RNF-NFR-212, RNF-NFR-221; T08 §16.1</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: integración</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Usuarios: USR-ADM-A (admin TEN-001, MFA requerido), USR-CAJ-01 (cajero), USR-DPO-A (responsable de datos TEN-001), USR-AUD-A (auditor), USR-ADM-B (admin TEN-002), USR-PLAT-01 (plataforma), USR-SRE-01</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Pedido de Internet que pasa por CRM, técnica, contratos y ERP sin que un reintento genere dos contratos o dos facturas.</li><li>Entonces RNF-NFR-212 a 215, RNF-NFR-221.</li></ul><p><strong>CP-NFR-8006 — CU-NFR-01. Un socio pide acceso a sus datos</strong></p><ul><li>Cubre: CU-NFR-01; RNF-NFR-107; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001 y TEN-002; semillas de T08 §18.</li><li>Datos de prueba: Personas: ASO-001 (socia, con MFA), ASO-002 y ASO-003 (hermanos, mismo domicilio ficticio), ADH-001 (menor adherente con representante ASO-002); documentos y CUIT generados con dígito verificador válido en rango ficticio; correos…</li><li>Dado actor: socia ficticia ASO-001 de TEN-001. Desde PAN-NFR-09 pide &quot;Descargar mis datos&quot;. Como está autenticada con MFA la solicitud queda <code>verificada</code>; JOB-NFR-02 localiza sus datos y JOB-NFR-01 genera el informe. El responsable de datos revisa y aprueba; la socia recibe aviso y descarga el PDF por URL firmada de 5 min. Control: el informe no incluye datos de su hermano que comparte domicilio (escenario 88) ni de…</li><li>Cuando Un socio pide acceso a sus datos</li><li>Entonces Actor: socia ficticia ASO-001 de TEN-001. Desde PAN-NFR-09 pide &quot;Descargar mis datos&quot;. Como está autenticada con MFA la solicitud queda <code>verificada</code>; JOB-NFR-02 localiza sus datos y JOB-NFR-01 genera el informe. El responsable de datos revisa y aprueba; la socia recibe aviso y descarga el PDF por URL firmada de 5 min. Control: el informe no incluye datos de su hermano que comparte domicilio (escenario 88) ni de TEN-002. Plazo: ≤ 10 días corridos (RNF-NFR-107).</li></ul><p><strong>CP-NFR-8007 — CU-NFR-02. Supresión con obligación de conservación</strong></p><ul><li>Cubre: CU-NFR-02; RN-NFR-017; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Registro de tratamientos: Plantilla completa de 12 finalidades (RF-NFR-002) en TEN-001; TEN-002 con 3 personalizadas</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Supresión con obligación de conservación</li><li>Entonces Un ex-socio sin servicios activos pide la supresión. Tiene facturas de hace 3 años. El análisis propone: suprimir teléfono, correo, preferencias, consentimientos promocionales y comentarios del muro; bloquear facturas, recibos y contrato (PRM-NFR-040/041) hasta su vencimiento; anonimizar tickets cerrados. Aprobación por un segundo usuario; EVT-NFR-06 a cada módulo; registro en <code>erasureLedger</code>; respuesta fundada al titular. Control: ninguna factura se borra (RN-NFR-017).</li></ul><p><strong>CP-NFR-8008 — CU-NFR-03. Revocación de consentimiento promocional</strong></p><ul><li>Cubre: CU-NFR-03; RF-NFR-005; T08 §16.2</li><li>Ola: O2 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O2 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Avisos: AVI-DEMO-001 v1 y v2 (landing), AVI-DEMO-002 v1 (app)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Revocación de consentimiento promocional</li><li>Entonces El socio desactiva &quot;Novedades comerciales&quot; en PWA. EVT-NFR-03 llega a COM y en ≤ 5 min queda fuera de audiencias promocionales; sigue recibiendo avisos de factura y corte (transaccionales, RF-NFR-005).</li></ul><p><strong>CP-NFR-8009 — CU-NFR-04. Incidente: credencial de pasarela expuesta</strong></p><ul><li>Cubre: CU-NFR-04; RNF-NFR-069; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001 y TEN-002; semillas de T08 §18.</li><li>Datos de prueba: Incidente: INC-2026-0001 tipo <code>simulacro</code>, SEV3, cerrado con post-mortem</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Incidente: credencial de pasarela expuesta</li><li>Entonces Una alerta de secret scanning detecta una credencial de sandbox en un PR (o una alerta de uso anómalo detecta uso de una credencial productiva). Se abre INC en <code>detectado</code>, se rota la credencial en la bóveda (≤ 4 h, RNF-NFR-069), se evalúa impacto, se notifica a la cooperativa en el plazo de PA-NFR-08 y se cierra con post-mortem.</li></ul><p><strong>CP-NFR-8010 — CU-NFR-05. Restauración selectiva con operaciones externas (ESC-04)</strong></p><ul><li>Cubre: CU-NFR-05; RNF-NFR-037; relacionados: ESC-04; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Simulacro: RST-DEMO-001 restauración selectiva de TEN-001 con RPO medido 4 min y RTO 3 h 10 min (valores ilustrativos)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Restauración selectiva con operaciones externas (ESC-04)</li><li>Entonces Un operador de TEN-001 importa por error un archivo que sobrescribe domicilios de 5.000 cuentas. El tenant solicita restauración (API-NFR-21). Plataforma restaura TEN-001 a T−2 h en ambiente aislado (RNF-NFR-037), compara y reincorpora solo domicilios; JOB-NFR-19 verifica que los pagos confirmados y los CAE obtenidos después de T−2 h se conservan; JOB-NFR-15 reaplica supresiones. TEN-002 no se afecta.</li></ul><p><strong>CP-NFR-8011 — CU-NFR-06. Lote interrumpido y reanudado</strong></p><ul><li>Cubre: CU-NFR-06; RNF-NFR-010, RNF-NFR-213; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Dataset de carga: Generador <code>seed:carga --perfil=grande</code> con 150.000 suministros y 5 años de movimientos sintéticos, solo en staging</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Lote interrumpido y reanudado</li><li>Entonces Durante <code>fac:emitir-lote</code> de 50.000 suministros cae un worker al 60 %. El lote se reanuda desde el checkpoint en ≤ 2 min, termina dentro de la meta (RNF-NFR-010) y no hay comprobantes duplicados (índice único RNF-NFR-213; escenario 6).</li></ul><p><strong>CP-NFR-8012 — CU-NFR-07. Tenant ruidoso</strong></p><ul><li>Cubre: CU-NFR-07; RNF-NFR-020, RNF-NFR-021; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Registro de tratamientos: Plantilla completa de 12 finalidades (RF-NFR-002) en TEN-001; TEN-002 con 3 personalizadas</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Tenant ruidoso</li><li>Entonces TEN-002 lanza la exportación completa de su historia mientras TEN-001 cobra en 30 cajas. La exportación corre en cola <code>bulk</code> con cuota (RNF-NFR-020, 021); los cobros de TEN-001 mantienen p95 ≤ 800 ms (AGR-020).</li></ul><p><strong>CP-NFR-8013 — CU-NFR-08. Archivo infectado</strong></p><ul><li>Cubre: CU-NFR-08; RNF-NFR-078; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Incidente: INC-2026-0001 tipo <code>simulacro</code>, SEV3, cerrado con post-mortem</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Archivo infectado</li><li>Entonces Un técnico sube una foto que en realidad es un ejecutable renombrado: se rechaza por firma de contenido (RNF-NFR-078). Un PDF con malware pasa el tipo pero el antivirus lo detecta: queda en cuarentena, la orden sigue sin el adjunto y se genera EVT-NFR-16.</li></ul><p><strong>CP-NFR-8014 — CU-NFR-09. Liberación bloqueada</strong></p><ul><li>Cubre: CU-NFR-09; RNF-NFR-148, RNF-NFR-165; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001 y TEN-002; semillas de T08 §18.</li><li>Datos de prueba: Evidencia: Release 0.0.1-demo con todos los checks en verde y un SCA con una vulnerabilidad media aceptada con vencimiento</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Liberación bloqueada</li><li>Entonces Una versión tiene una vulnerabilidad alta en una dependencia y una ruta nueva sin caso de aislamiento; el pipeline bloquea la promoción a producción (RNF-NFR-148, RNF-NFR-165) hasta corregir.</li></ul><p><strong>CP-NFR-8015 — CU-NFR-10. Rotación de DEK de un tenant</strong></p><ul><li>Cubre: CU-NFR-10; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001 y TEN-002; semillas de T08 §18.</li><li>Datos de prueba: Claves: Metadatos de DEK por tenant (sin material), una en <code>soloDescifrado</code></li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Rotación de DEK de un tenant</li><li>Entonces Por política anual se rota la DEK general de TEN-001: se crea la versión nueva, la anterior pasa a <code>soloDescifrado</code>, JOB-NFR-08 re-cifra en segundo plano sin indisponibilidad y la consola muestra el progreso.</li></ul><p><strong>CP-NFR-8016 — CU-NFR-11. Pago excedente con webhook duplicado (ESC-01 + escenario 7)</strong></p><ul><li>Cubre: CU-NFR-11; relacionados: ESC-01; T08 §16.2</li><li>Ola: O1 · Prioridad: Núcleo · Tipo: integración</li><li>Precondiciones: ola O1 desplegada; tenant ficticio TEN-001; semillas de T08 §18.</li><li>Datos de prueba: Tenants: TEN-001 &quot;Cooperativa Ejemplo A&quot; (<code>America/Argentina/Cordoba</code>), TEN-002 &quot;Cooperativa Ejemplo B&quot; (<code>America/Argentina/Buenos_Aires</code>), TEN-099 &quot;Cooperativa en baja&quot; (para RNF-NFR-108); todos con <code>isFictitious: true</code></li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Pago excedente con webhook duplicado (ESC-01 + escenario 7)</li><li>Entonces Hermano A (deuda ARS 13.000) paga ARS 15.000 por pasarela; el webhook llega 3 veces. Se confirma un solo pago, se imputan ARS 13.000 y ARS 2.000 quedan a favor; B no se ve afectado.</li></ul>',52)])])}const N=a(t,[["render",n]]);export{R as __pageData,N as default};
